#!/usr/bin/env python3
"""Offline EPIC collective collector: JSON stdin/stdout entry point.

One UTF-8 JSON batch request is read from stdin. The whole batch is validated
first (see request.py, the public format-only validator); an illegal request
produces exactly {"error":"invalid"} with exit status zero and no replay or
compilation work. Otherwise each case is replayed offline and its certificate
is printed as one JSON object.
"""
import json
import os
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

MAX_INPUT = 4 * 1024 * 1024
INVALID = '{"error":"invalid"}'


def _load_request(raw):
    """Validate the entire batch before any replay work happens."""
    from request import load
    return load(raw)


def _run_case(case):
    from collector import Case, PRIM_INDEX
    run = Case(PRIM_INDEX[case['primitive']], case['mode'], case['root'],
               case['segments'], case['words'], case['capacity'],
               case['start'], case.get('trace', 0))
    run.replay(case['events'])
    return run.certificate()


def solve(request):
    cases = request['cases']
    if not cases:
        return {'cases': []}
    import collector
    collector.use_accelerator()
    return {'cases': [_run_case(case) for case in cases]}


def _emit(text):
    sys.stdout.write(text)
    sys.stdout.flush()
    os._exit(0)


def main():
    try:
        raw = sys.stdin.buffer.read(MAX_INPUT + 1)
    except Exception:
        _emit(INVALID)
    try:
        request = _load_request(raw)
    except Exception:
        _emit(INVALID + '\n')
    _emit(json.dumps(solve(request), separators=(',', ':'), allow_nan=False)
          + '\n')


if __name__ == '__main__':
    main()
PYEOF
